198	export const TRACK = { ink: '#F2F4F7', warn: '#F2B441', extra: '#F2F4F7', mark: '#9AA4B2', empty: '#2A303B' };   // ink · warn · ink (trả thêm) · ink-muted · grid (E2)
199	const mat = (c, o = {}) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.8, transparent: true, ...o });
200	const cl01 = (x) => Math.min(1, Math.max(0, x));
