202	// ---------------------------------------------------------------- N1 đường tháng (gốc toạ độ = góc trước-trái của ô 1 trên sàn)
203	export function MonthTrack({ n = 180, cols = 12, spare = 2, tile = 0.34, gap = 0.08, th = 0.07, slab = 0.035, name = 'track' } = {}) {
204	  const g = new THREE.Group(), pitch = tile + gap, years = Math.ceil(n / cols), nmax = n + spare * cols;
205	  const box = (h, f = 1) => new THREE.BoxGeometry(tile * f, h, tile * f);
206	  // lớp trả thêm phủ 72 % mặt ô (vành ink-muted của khoản bắt buộc vẫn thấy); khi gom, lớp chồng lên nhau cách SG → khối = 12 lớp đếm được
207	  const SF = 0.72, SG = 0.006;
208	  const tiles = new THREE.InstancedMesh(box(th), mat('#FFFFFF', { emissive: new THREE.Color('#FFFFFF'), emissiveIntensity: 0 }), nmax);
209	  const slabs = new THREE.InstancedMesh(box(slab, SF), mat(TRACK.extra, { emissive: new THREE.Color(TRACK.extra), emissiveIntensity: 0.8 }), n);
210	  for (const m of [tiles, slabs]) { m.castShadow = m.receiveShadow = true; m.frustumCulled = false; g.add(m); }
211	  // vạch 15 năm: thanh mảnh đứng yên dọc theo cột, ngay sau ô n (giữa cột years-1 và years)
212	  const markX = years * pitch - gap / 2, depth = cols * pitch - gap;
213	  const mark = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.32, depth + 0.5), mat(TRACK.mark, { emissive: new THREE.Color(TRACK.mark), emissiveIntensity: 0.4 }));
214	  mark.position.set(markX, 0.16, -depth / 2 + tile / 2); mark.castShadow = true; g.add(mark);
215	  const pos = (i) => [Math.floor(i / cols) * pitch + tile / 2, -(i % cols) * pitch];   // x, z của tâm ô i (0-based)
216	  const M = new THREE.Matrix4(), col = new THREE.Color(), C = { req: new THREE.Color(TRACK.mark), warn: new THREE.Color(TRACK.warn), empty: new THREE.Color(TRACK.empty) };
217	  const hide = new THREE.Matrix4().makeScale(0, 0, 0);
218	  tiles.userData.checks = { role: 'mark', series: name, key: `track-${name}-tiles` };
219	  slabs.userData.checks = { role: 'mark', series: name, key: `track-${name}-extra` };
220	  mark.userData.checks = { role: 'mark', series: name, key: `track-${name}-mark` };
221	  g.userData = { n, cols, pitch, tile, th, years, nmax, markX, depth, slab, SG };
222	  const sm = (u) => u * u * (3 - 2 * u);
223	  // lit: số ô thường đã đặt (0 … n, thực: ô cuối mọc dần); late: số ô trễ (warn, thực); extra: số cột-năm (0 … years, thực) đã có lớp mỏng,
224	  // trái → phải; gathered: số cột-năm (từ trái, thực) mà 12 lớp đã trượt về ô thứ 12 thành một khối (phần lẻ = đang trượt; lớp xa ô 12
225	  // khởi hành muộn hơn, đến sau, nằm trên cùng) — hoặc mảng tiến độ [0,1] từng cột (nhiều cột trượt cùng lúc); markA ∈ [0,1]: vạch 15 năm; pulse ∈ [0,1]: loé nhẹ ô trễ
226	  g.set = ({ lit = n, late = 0, extra = 0, gathered = 0, markA = 1, pulse = 0 } = {}) => {
227	    for (let i = 0; i < nmax; i++) {
228	      const [x, z] = pos(i), isLate = i >= n, a = isLate ? cl01(late - (i - n)) : cl01(lit - i);
229	      if (a <= 0.002) { tiles.setMatrixAt(i, hide); continue; }
230	      const s = isLate ? 1 : a;   // ô thường mọc từ sàn; ô trễ hiện đủ cỡ, sáng theo phần (như W10)
231	      M.makeScale(1, s, 1).setPosition(x, th * s / 2, z); tiles.setMatrixAt(i, M);
232	      col.copy(C.empty).lerp(isLate ? C.warn : C.req, isLate ? a * (0.85 + 0.15 * pulse) : 1); tiles.setColorAt(i, col);
233	    }
234	    const zEnd = pos(cols - 1)[1];
235	    for (let i = 0; i < n; i++) {
236	      const c = Math.floor(i / cols), r = i % cols, a = cl01(extra - c) * cl01(lit - i), [x, z] = pos(i);
237	      if (a <= 0.002) { slabs.setMatrixAt(i, hide); continue; }
238	      const gp = Array.isArray(gathered) ? (gathered[c] || 0) : cl01(gathered - c);
239	      const k = cols - 1 - r, dl = 0.35 * k / (cols - 1), e = sm(cl01((gp - dl) / (1 - dl)));
240	      const y0 = th + slab * a / 2 + 0.002, y1 = th + 0.002 + k * (slab + SG) + slab / 2;
241	      M.makeScale(1, a, 1).setPosition(x, y0 + (y1 - y0) * e + 0.05 * Math.sin(Math.PI * e), z + (zEnd - z) * e); slabs.setMatrixAt(i, M);
242	    }
243	    for (const m of [tiles, slabs]) m.instanceMatrix.needsUpdate = true;
244	    if (tiles.instanceColor) tiles.instanceColor.needsUpdate = true;
245	    mark.material.opacity = markA; mark.visible = markA > 0.01;
246	    tiles.userData.checks.level = +Math.min(n, lit).toFixed(2); tiles.userData.checks.late = +late.toFixed(2);
247	    slabs.userData.checks.level = +extra.toFixed(3); slabs.userData.checks.gathered = Array.isArray(gathered) ? +gathered.reduce((s, v) => s + v, 0).toFixed(3) : +gathered.toFixed(3);
248	  };
249	  // đỉnh khối năm của cột c (toạ độ thế giới) — cho nhãn S23
250	  g.blockTop = (c) => { const [x, z] = pos(c * cols + cols - 1); return [g.position.x + x, g.position.y + th + cols * (slab + SG), g.position.z + z]; };
251	  // toạ độ thế giới (đã cộng vị trí nhóm) — cho nhãn/ngoặc ở lớp phủ: tâm ô i, mép trái/phải của cột c, mép trước/sau
252	  g.tileAt = (i) => { const [x, z] = pos(i); return [g.position.x + x, g.position.y + th, g.position.z + z]; };
253	  g.colX = (c, side = 0) => g.position.x + c * pitch + (side < 0 ? 0 : side > 0 ? tile : tile / 2);
254	  g.frontZ = () => g.position.z + tile / 2;
255	  g.backZ = () => g.position.z - (cols - 1) * pitch - tile / 2;
256	  g.markWorldX = () => g.position.x + markX;
257	  g.set({});
258	  return g;
259	}
