425	        a = max(0.0, float(min(w['s'] for w in ws)) - pre); b = float(max(w['e'] for w in ws)) + tail
426	        wav = os.path.join(out_dir, f"{W['hash']}-{a:.3f}-{b:.3f}.wav")
