// chế độ đồ thị: sàn + sương lùi đi (như Tập 5/6)
export function modeLook(scene, floor, cw) { floor.material.opacity = 1 - 0.85 * cw; scene.fog.near = 30 + 120 * cw; scene.fog.far = 80 + 220 * cw; }

// lớp bắt buộc (như c3kit.js Tập 6): ILLUSTRATIVE (mọi khung có Tessa), nguồn + "US only · history, not a forecast" (mọi khung)
export function chrome(O) { O.chrome({ illus: true, src: 'Freddie Mac weekly mortgage survey', hist: true }); }

// ngoặc ngang (nét lớp phủ, toạ độ thiết kế); tick > 0 = chân xuống, < 0 = chân lên
export function brace(O, x0, x1, y, color, a, lw = 5, tick = 14) {
  if (a <= 0.01) return; const c = O.ctx; c.save(); c.globalAlpha = a; c.strokeStyle = color; c.lineWidth = lw;
  c.beginPath(); c.moveTo(x0, y + tick); c.lineTo(x0, y); c.lineTo(x1, y); c.lineTo(x1, y + tick); c.stroke(); c.restore();
}
export function label(O, s, x, y, o = {}) { return O.text(s, x, y, o.px || 52, { plate: PLATE, plateA: 0.72, ...o }); }
export { C, THREE, setOpacity, ease };
// Tập 7 · VẬT THỂ MỚI (C3, D-010 quy tắc 4) — chưa vào lib3d.js (không sửa toolkit trong phiên này). Gen kênh: low-poly, màu kênh (E2).
//  N1 MonthTrack — "đường tháng": một ô = MỘT khoản trả tháng; ô giống hệt nhau; trái → phải = thời gian.
//   Bố cục lịch: cột = một năm (cols = 12 ô), cột nối nhau trái → phải; trong cột, tháng 1 ở mép trước (+z), tháng 12 ở mép sau.
//   180 ô = 15 cột đủ. Ô quá n (trễ) = warn, sáng theo PHẦN như W10 (14,6 → 14 ô đủ + ô thứ 15 sáng 60 %). Vạch 15 năm (sau ô n) = ink-muted, đứng yên.
//   Màu theo vai E2 (beats.md Colour roles, vòng 3): ô khoản bắt buộc = ink-muted ("the required-payment level"), lớp trả thêm của Tessa = ink
//   ("the payments", sáng, nổi trên ô). Trả thêm: lớp mỏng trên mỗi ô (extra); gom (S23): 12 lớp của một cột-năm TRƯỢT về ô thứ 12 và chồng
//   lên nhau thành một khối 12 lớp (cùng tổng).
//  PayBar — thanh khoản trả tháng (ink), phần trên mức warnAbove = warn (giá của khoản dự phòng). Chiều cao = USD × scale.
//  Bill — một tờ đô la low-poly (màu vật liệu tiền của lib3d, không chữ) cho S25.
import * as THREE from 'three';

export const TRACK = { ink: '#F2F4F7', warn: '#F2B441', extra: '#F2F4F7', mark: '#9AA4B2', empty: '#2A303B' };   // ink · warn · ink (trả thêm) · ink-muted · grid (E2)
const mat = (c, o = {}) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.8, transparent: true, ...o });
const cl01 = (x) => Math.min(1, Math.max(0, x));

// ---------------------------------------------------------------- N1 đường tháng (gốc toạ độ = góc trước-trái của ô 1 trên sàn)
export function MonthTrack({ n = 180, cols = 12, spare = 2, tile = 0.34, gap = 0.08, th = 0.07, slab = 0.035, name = 'track' } = {}) {
  const g = new THREE.Group(), pitch = tile + gap, years = Math.ceil(n / cols), nmax = n + spare * cols;
  const box = (h, f = 1) => new THREE.BoxGeometry(tile * f, h, tile * f);
  // lớp trả thêm phủ 72 % mặt ô (vành ink-muted của khoản bắt buộc vẫn thấy); khi gom, lớp chồng lên nhau cách SG → khối = 12 lớp đếm được
  const SF = 0.72, SG = 0.006;
  const tiles = new THREE.InstancedMesh(box(th), mat('#FFFFFF', { emissive: new THREE.Color('#FFFFFF'), emissiveIntensity: 0 }), nmax);
  const slabs = new THREE.InstancedMesh(box(slab, SF), mat(TRACK.extra, { emissive: new THREE.Color(TRACK.extra), emissiveIntensity: 0.8 }), n);
  for (const m of [tiles, slabs]) { m.castShadow = m.receiveShadow = true; m.frustumCulled = false; g.add(m); }
  // vạch 15 năm: thanh mảnh đứng yên dọc theo cột, ngay sau ô n (giữa cột years-1 và years)
  const markX = years * pitch - gap / 2, depth = cols * pitch - gap;
  const mark = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.32, depth + 0.5), mat(TRACK.mark, { emissive: new THREE.Color(TRACK.mark), emissiveIntensity: 0.4 }));
  mark.position.set(markX, 0.16, -depth / 2 + tile / 2); mark.castShadow = true; g.add(mark);
  const pos = (i) => [Math.floor(i / cols) * pitch + tile / 2, -(i % cols) * pitch];   // x, z của tâm ô i (0-based)
  const M = new THREE.Matrix4(), col = new THREE.Color(), C = { req: new THREE.Color(TRACK.mark), warn: new THREE.Color(TRACK.warn), empty: new THREE.Color(TRACK.empty) };
  const hide = new THREE.Matrix4().makeScale(0, 0, 0);
  tiles.userData.checks = { role: 'mark', series: name, key: `track-${name}-tiles` };
  slabs.userData.checks = { role: 'mark', series: name, key: `track-${name}-extra` };
  mark.userData.checks = { role: 'mark', series: name, key: `track-${name}-mark` };
  g.userData = { n, cols, pitch, tile, th, years, nmax, markX, depth, slab, SG };
  const sm = (u) => u * u * (3 - 2 * u);
  // lit: số ô thường đã đặt (0 … n, thực: ô cuối mọc dần); late: số ô trễ (warn, thực); extra: số cột-năm (0 … years, thực) đã có lớp mỏng,
  // trái → phải; gathered: số cột-năm (từ trái, thực) mà 12 lớp đã trượt về ô thứ 12 thành một khối (phần lẻ = đang trượt; lớp xa ô 12
  // khởi hành muộn hơn, đến sau, nằm trên cùng) — hoặc mảng tiến độ [0,1] từng cột (nhiều cột trượt cùng lúc); markA ∈ [0,1]: vạch 15 năm; pulse ∈ [0,1]: loé nhẹ ô trễ
  g.set = ({ lit = n, late = 0, extra = 0, gathered = 0, markA = 1, pulse = 0 } = {}) => {
    for (let i = 0; i < nmax; i++) {
      const [x, z] = pos(i), isLate = i >= n, a = isLate ? cl01(late - (i - n)) : cl01(lit - i);
      if (a <= 0.002) { tiles.setMatrixAt(i, hide); continue; }
      const s = isLate ? 1 : a;   // ô thường mọc từ sàn; ô trễ hiện đủ cỡ, sáng theo phần (như W10)
      M.makeScale(1, s, 1).setPosition(x, th * s / 2, z); tiles.setMatrixAt(i, M);
      col.copy(C.empty).lerp(isLate ? C.warn : C.req, isLate ? a * (0.85 + 0.15 * pulse) : 1); tiles.setColorAt(i, col);
    }
    const zEnd = pos(cols - 1)[1];
    for (let i = 0; i < n; i++) {
      const c = Math.floor(i / cols), r = i % cols, a = cl01(extra - c) * cl01(lit - i), [x, z] = pos(i);
      if (a <= 0.002) { slabs.setMatrixAt(i, hide); continue; }
      const gp = Array.isArray(gathered) ? (gathered[c] || 0) : cl01(gathered - c);
      const k = cols - 1 - r, dl = 0.35 * k / (cols - 1), e = sm(cl01((gp - dl) / (1 - dl)));
      const y0 = th + slab * a / 2 + 0.002, y1 = th + 0.002 + k * (slab + SG) + slab / 2;
      M.makeScale(1, a, 1).setPosition(x, y0 + (y1 - y0) * e + 0.05 * Math.sin(Math.PI * e), z + (zEnd - z) * e); slabs.setMatrixAt(i, M);
    }
    for (const m of [tiles, slabs]) m.instanceMatrix.needsUpdate = true;
    if (tiles.instanceColor) tiles.instanceColor.needsUpdate = true;
    mark.material.opacity = markA; mark.visible = markA > 0.01;
    tiles.userData.checks.level = +Math.min(n, lit).toFixed(2); tiles.userData.checks.late = +late.toFixed(2);
    slabs.userData.checks.level = +extra.toFixed(3); slabs.userData.checks.gathered = Array.isArray(gathered) ? +gathered.reduce((s, v) => s + v, 0).toFixed(3) : +gathered.toFixed(3);
  };
  // đỉnh khối năm của cột c (toạ độ thế giới) — cho nhãn S23
  g.blockTop = (c) => { const [x, z] = pos(c * cols + cols - 1); return [g.position.x + x, g.position.y + th + cols * (slab + SG), g.position.z + z]; };
  // toạ độ thế giới (đã cộng vị trí nhóm) — cho nhãn/ngoặc ở lớp phủ: tâm ô i, mép trái/phải của cột c, mép trước/sau
  g.tileAt = (i) => { const [x, z] = pos(i); return [g.position.x + x, g.position.y + th, g.position.z + z]; };
  g.colX = (c, side = 0) => g.position.x + c * pitch + (side < 0 ? 0 : side > 0 ? tile : tile / 2);
  g.frontZ = () => g.position.z + tile / 2;
  g.backZ = () => g.position.z - (cols - 1) * pitch - tile / 2;
  g.markWorldX = () => g.position.x + markX;
  g.set({});
  return g;
}

// ---------------------------------------------------------------- thanh khoản trả tháng: ink tới warnAbove, phần trên = warn (gốc = tâm đáy)
export function PayBar({ w = 0.8, d = 0.5, scale = 1 / 1200, name = 'bar' } = {}) {
  const g = new THREE.Group();
  const base = new THREE.Mesh(new THREE.BoxGeometry(w, 1, d), mat(TRACK.ink, { emissive: new THREE.Color(TRACK.ink), emissiveIntensity: 0.12 }));
  const top = new THREE.Mesh(new THREE.BoxGeometry(w, 1, d), mat(TRACK.warn, { emissive: new THREE.Color(TRACK.warn), emissiveIntensity: 0.3 }));
  for (const m of [base, top]) { m.castShadow = m.receiveShadow = true; g.add(m); }
  base.userData.checks = { role: 'bar', series: name, key: `pay-${name}` }; top.userData.checks = { role: 'bar', series: name, key: `pay-${name}-above` };
  g.userData = { w, d, scale };
  // usd: chiều cao (USD/tháng); warnAbove: mức trên đó tô warn; topA ∈ [0,1]: độ hiện phần warn; appear ∈ [0,1]
  g.set = ({ usd = 0, warnAbove = Infinity, topA = 1, appear = 1 } = {}) => {
    const h = usd * scale * appear, hb = Math.min(h, warnAbove * scale), ht = Math.max(0, h - hb);
    base.scale.y = Math.max(0.001, hb); base.position.y = hb / 2; base.visible = hb > 0.002;
    top.scale.y = Math.max(0.001, ht); top.position.y = hb + ht / 2; top.visible = ht > 0.002 && topA > 0.01;
    top.material.color.set(TRACK.ink).lerp(new THREE.Color(TRACK.warn), topA);
    base.userData.checks.value = +Math.min(usd, warnAbove).toFixed(2); top.userData.checks.value = +Math.max(0, usd - warnAbove).toFixed(2);
    return h;
  };
  g.topY = (usd) => usd * scale;
  g.set({});
  return g;
}

// ---------------------------------------------------------------- tờ đô la (thẻ phẳng màu tiền + huy hiệu tròn sáng ở giữa; không chữ)
export function Bill({ w = 0.62, h = 0.28, d = 0.02, name = 'bill' } = {}) {
  const g = new THREE.Group();
  const body = new THREE.Mesh(new THREE.BoxGeometry(w, d, h), mat('#5E8C6A', { roughness: 0.7 })); body.castShadow = body.receiveShadow = true;
  const seal = new THREE.Mesh(new THREE.CylinderGeometry(h * 0.3, h * 0.3, d * 1.3, 12), mat('#C9D8C4', { roughness: 0.6 }));
  const edge = new THREE.Mesh(new THREE.BoxGeometry(w * 0.9, d * 1.2, h * 0.08), mat('#4E7A5A')); edge.position.z = h * 0.36;
  const edge2 = edge.clone(); edge2.position.z = -h * 0.36;
  g.add(body, seal, edge, edge2);
  g.userData.checks = { role: 'mark', series: name, key: `bill-${name}` };
  return g;
}
"""Tập 7 · dữ liệu hình cho các đoạn thế giới 3D (C3), dẫn xuất từ out/model.json + numbers.md của tập (không sửa mô hình).
  python3 episodes/ep007/world/derive.py → episodes/ep007/world/claims.json
claims.json = claim hiển thị {value, display, display_full}: value chép từ out/model.json; display = chuỗi đúng như trên hình, luôn là một
đoạn NGUYÊN VẸN của cột "Hiển thị" (display_full) trong numbers.md — kiểm ở đây (thiếu/không khớp → dừng).
Ngoại lệ có ghi: `principal` = params.principal của model.json ($320,000, khoản vay minh hoạ; không có dòng claim riêng trong numbers.md).
Kiểm chéo số học: tổng chồng = 15 bó năm (bundle = extra_vs15_total_now / 15 ≈ 12 × $120), tháng trễ = 195 − 180, 184 − 180 = 4."""
import json, os, re
HERE = os.path.dirname(os.path.abspath(__file__)); EP = os.path.dirname(HERE)
model = json.load(open(os.path.join(EP, 'out/model.json'))); Q = model['quantities']
rows = {}
for ln in open(os.path.join(EP, 'numbers.md'), encoding='utf-8'):
    m = re.match(r'^\| `(\w+)` \| ([^|]+) \| ([^|]+) \|', ln)
    if m: rows[m.group(1)] = m.group(3).strip()

# chuỗi hiển thị trên hình (mỗi chuỗi là đoạn nguyên vẹn của cột Hiển thị); mọi số trên hình đi qua đây
disp = {'extra_vs15_month_now': '$120 a month', 'extra_vs15_total_now': '$21,622', 'pay30on15_now': '$2,948 a month', 'pay15_now': '$2,828',
        'last_week': 'October 8, 2026', 'months_at_pay15_now': 'about 195 months', 'months_late_at_pay15_now': 'about 15 months late',
        'extra_principal_needed_now': '$733 a month', 'monthly_extra_months': '180 months', 'yearly_lump': '$8,792 once a year',
        'yearly_lump_months': '184 months', 'bar_now': '7.40% a year, before taxes', 'r30_now': '7.40%', 'pay30_now': '$2,216 a month'}
cl = {}
for k, d in disp.items():
    full = rows[k]
    assert d in full, f'{k}: "{d}" không nằm trong cột Hiển thị "{full}"'
    cl[k] = {'value': Q[k]['value'], 'display': d, 'display_full': full}
# hiển thị rút gọn của ngày (nhãn ≤ ~8 từ): "Oct 8, 2026" — cùng ngày last_week; ghi riêng để trang kiểm khớp chuỗi trên hình
assert Q['last_week']['value'] == '2026-10-08'
cl['last_week_short'] = {'value': '2026-10-08', 'display': 'Oct 8, 2026', 'display_full': rows['last_week'], 'of': 'last_week'}
cl['yearly_lump_late'] = {'value': Q['yearly_lump_months']['value'] - 180, 'display': '4 months later', 'display_full': rows['yearly_lump_months'], 'of': 'yearly_lump_months'}
assert '4 months later' in rows['yearly_lump_months'] and Q['yearly_lump_months']['value'] - 180 == 4
# s06 (vòng 2): khoản 15 năm ghi kèm "a month" cạnh vạch mức 15 năm — cùng claim pay15_now, chuỗi = cả cột Hiển thị
cl['pay15_month'] = {'value': Q['pay15_now']['value'], 'display': '$2,828 a month', 'display_full': rows['pay15_now'], 'of': 'pay15_now'}
assert cl['pay15_month']['display'] in rows['pay15_now']
# s21 (vòng 3): "to finish in 180 months: $2,216 required + $733 a month" — khoản bắt buộc không kèm "a month" (đoạn nguyên vẹn của Hiển thị)
cl['pay30_amt'] = {'value': Q['pay30_now']['value'], 'display': '$2,216', 'display_full': rows['pay30_now'], 'of': 'pay30_now'}
assert cl['pay30_amt']['display'] in rows['pay30_now']
cl['principal'] = {'value': model['params']['principal'], 'display': '$320,000', 'display_full': '$320,000 (params.principal; ILLUSTRATIVE loan)'}
assert model['params']['principal'] == 320000

# kiểm chéo dùng cho hình
v = lambda k: Q[k]['value']
assert abs(v('months_at_pay15_now') - 180 - v('months_late_at_pay15_now')) < 0.05
assert v('monthly_extra_months') == 180 and round(v('extra_vs15_month_now')) == 120
assert abs(v('extra_vs15_month_now') * 180 - v('extra_vs15_total_now')) < 1
geom = {'bundle_usd': round(v('extra_vs15_total_now') / 15, 2), 'late_months': round(v('months_late_at_pay15_now'), 1),
        'lump_late_months': v('yearly_lump_months') - 180, 'pay15': v('pay15_now'), 'pay30': v('pay30_now'), 'pay30on15': v('pay30on15_now'),
        'stack_total': v('extra_vs15_total_now'), 'bar': v('bar_now')}
cl['_geom'] = geom
json.dump(cl, open(os.path.join(HERE, 'claims.json'), 'w'), indent=1, ensure_ascii=False)
print('claims', len(cl) - 1, 'geom', geom)
"""Tập 7 · tiện ích chung cho các đoạn thế giới 3D (spine v2, D-010) — chép từ episodes/ep006/world/wlib.py, đổi nguồn take:
take của cảnh theo episodes/ep007/world/c3/voice-scenes.json (sinh bằng world/c3/voice_c3.py, take commit ở voice-takes/).
  scene_take(sc)        → take của cảnh, kiểm chữ take == chữ kịch bản hiện tại
  scene_words(sc)       → từ (đã nói, có sid = câu kịch bản), đầu từ chỉnh theo năng lượng (onset.refine), giờ tính trong take
  clip_voice(runs, lead)→ lời cho một đoạn ngắn (C3): cắt từ take theo câu (wav trong work/, không commit), từ đã dời giờ
Không gọi API ở đây: thiếu take → dừng (SystemExit)."""
import json, os, re, subprocess, sys
HERE = os.path.dirname(os.path.abspath(__file__))
EP = os.path.dirname(HERE)
ROOT = os.path.abspath(os.path.join(EP, '..', '..'))
sys.path.insert(0, os.path.join(ROOT, 'toolkit', 'factory', 'world'))
sys.path.insert(0, os.path.join(ROOT, 'toolkit', 'factory'))
sys.dont_write_bytecode = True
from onset import refine  # noqa: E402
TAKES = os.path.join(EP, 'voice-takes')
SCENES = os.path.join(HERE, 'c3', 'voice-scenes.json')
LINE = re.compile(r'^(S\d\d)\.(\d+)\s+(?:\{(\w+)\}\s+)?(.+?)\s*<!--')
TAIL = 1.0


def script_rows():
    out = []
    for ln in open(os.path.join(EP, 'story', 'script.md'), encoding='utf-8'):
        m = LINE.match(ln)
        if m: out.append({'id': f'{m.group(1)}.{m.group(2)}', 'scene': m.group(1), 'text': m.group(4).strip()})
    return out


def voice_scenes():
    return json.load(open(SCENES))


def scene_take(sc):
    vs = voice_scenes()
    if sc not in vs: raise SystemExit(f'không có take cho {sc} trong voice-scenes.json — dừng (chạy world/c3/voice_c3.py)')
    h = vs[sc]['take'].replace('.mp3', '')
    mp3, js = os.path.join(TAKES, h + '.mp3'), os.path.join(TAKES, h + '.json')
    if not (os.path.exists(mp3) and os.path.exists(js)): raise SystemExit(f'take {h} của {sc} không có trong voice-takes/ — dừng')
    return h, mp3, json.load(open(js)), vs[sc]['duration']


_SPOKEN = {}


def spoken(rows):
    import voice as V                       # toolkit/factory/voice.py: chỉ dùng to_spoken (node, không mạng)
    key = tuple(r['text'] for r in rows)
    if key not in _SPOKEN: _SPOKEN[key] = V.to_spoken(list(key))
    return _SPOKEN[key]


def scene_words(sc, do_refine=True):
    h, mp3, meta, dur = scene_take(sc)
    rows = [r for r in script_rows() if r['scene'] == sc]
    sp = spoken(rows); text = ' '.join(sp)
    al = meta['alignment']
    if ''.join(al['characters']) != text or meta['text'] != text:
        raise SystemExit(f'{sc}: chữ take {h} khác chữ kịch bản hiện tại — dừng (cần đọc lại giọng)')
    st, en = al['character_start_times_seconds'], al['character_end_times_seconds']
    bounds, pos = [], 0
    for r, s in zip(rows, sp): bounds.append((r['id'], pos, pos + len(s))); pos += len(s) + 1
    words = []
    for m in re.finditer(r'\S+', text):
        sid = next(b[0] for b in bounds if b[1] <= m.start() < b[2])
        words.append({'w': m.group(0), 's': round(st[m.start()], 3), 'e': round(en[m.end() - 1], 3), 'sid': sid})
    if do_refine:
        words = refine(words, mp3)
    return {'hash': h, 'mp3': os.path.relpath(mp3, ROOT), 'duration': dur, 'words': words, 'lines': {r['id']: r['text'] for r in rows}}


def clip_voice(runs, lead=0.6, tail=0.25, pre=0.15, gap_same=0.6):
    """Lời cho một đoạn C3. runs = [[sid, sid…], …]: mỗi run là các câu LIỀN NHAU của một cảnh. Mỗi run: cắt take từ (đầu câu đầu − pre)
    tới (cuối câu cuối + tail) thành wav 48 kHz trong episodes/ep007/work/world-voice/ (không commit); run nối nhau cách 1,0 s
    (khác cảnh) hoặc gap_same (cùng cảnh, bỏ câu giữa). Trả (words, takes, lines, end) — takes theo audio.py ({'wav', 't'})."""
    out_dir = os.path.join(EP, 'work', 'world-voice'); os.makedirs(out_dir, exist_ok=True)
    t, words, takes, lines, prev = lead, [], [], {}, None
    for ss in runs:
        sc = ss[0][:3]
        if prev is not None: t += TAIL if sc != prev else gap_same
        W = scene_words(sc)
        ws = [w for w in W['words'] if w['sid'] in ss]
        if not ws or ws[0]['sid'] != ss[0] or ws[-1]['sid'] != ss[-1]: raise SystemExit(f'câu {ss} không có trong take {sc}')
        a = max(0.0, float(min(w['s'] for w in ws)) - pre); b = float(max(w['e'] for w in ws)) + tail
        wav = os.path.join(out_dir, f"{W['hash']}-{a:.3f}-{b:.3f}.wav")
        if not os.path.exists(wav):
            subprocess.run(['ffmpeg', '-v', 'error', '-y', '-ss', f'{a:.3f}', '-to', f'{b:.3f}', '-i', os.path.join(ROOT, W['mp3']), '-ar', '48000', '-ac', '1',
                            '-af', 'afade=t=in:d=0.02,afade=t=out:st={:.3f}:d=0.03'.format(b - a - 0.03), wav], check=True)
        words += [{'w': w['w'], 's': round(float(w['s']) - a + t, 3), 'e': round(float(w['e']) - a + t, 3), 'sid': w['sid'],
                   's_tts': round(float(w['s_tts']) - a + t, 3)} for w in ws]
        takes.append({'wav': os.path.relpath(wav, ROOT), 'mp3': W['mp3'], 'take': W['hash'], 'from': round(a, 3), 'to': round(b, 3), 't': round(t, 3)})
        lines.update({s: W['lines'][s] for s in ss})
        t += b - a; prev = sc
    return words, takes, lines, round(t, 3)


def music_plan_flat(total, accents):
    """Đoạn C3 ngắn: nhạc không tắt giữa đoạn (stop = cuối), điểm nhấn felt ở các mốc dữ liệu."""
    return {'stop': total, 'tau': 0.25, 'release': total + 1.0, 'accents': accents[:4]}

