  const door = [hm.house.position.x, BUNDLE_TH / 2 + 0.02, 0.58 + FLY_D / 2 + 0.05];   // bậc cửa (trước cửa nhà, lib3d House: cửa giữa mặt trước)
  const path = (k, p) => {   // bậc cửa → đỉnh chồng (bó thứ k), vòng ra trước rồi hạ xuống
