    return [door[0] + (stack.position.x - door[0]) * e, door[1] + (ye - door[1]) * e + 0.55 * Math.sin(Math.PI * p), door[2] * (1 - e) + 0.35 * Math.sin(Math.PI * p)];
  };

  function frame(t) {
    const pose = CAM.apply(t), cw = pose.chart, cam = CAM.cam;
    modeLook(scene, floor, cw);
