  const cardA = OfferCard(scene, { x: S.cards[0], y: 2.6, w: 3.0, h: 0.8 }), cardB = OfferCard(scene, { x: S.cards[1], y: 2.6, w: 3.0, h: 0.8 });
  const strip = WeekStrip(scene, S.weeks_extra, { x0: -9, width: 15, z: -3.2 });
