      f.position.set(mix(x0, x1, p), mix(y0, y1, p) + 1.6 * Math.sin(Math.PI * p), mix(z0, 0, p) + 0.6 * Math.sin(Math.PI * p)); f.scale.set(1, 0.92, 1);
