  };
  // thẻ: hiện ở từ khoá, mờ khi lùi máy ra dải tuần (dải nằm sau thẻ), về lại khi đẩy máy về thẻ
  const cardsA = (t) => 1 - ease(t, MV.m_pull.t0, MV.m_pull.t0 + 0.5) + ease(t, MV.m_push.t0 + 0.3, MV.m_push.t1);

